// Group tasks by urgency and work_group, format for notifications
const tasks = $input.all();

if (tasks.length === 0) {
  return {
    json: {
      hasTasks: false,
      message: "No tasks due soon",
      execution_id: $execution.id || `exec_${Date.now()}`
    }
  };
}

// Group by urgency and work_group
const grouped = {};
tasks.forEach(task => {
  const level = task.json.urgency_level || 'due_3_days';
  const group = task.json.work_group || 'chung';
  const key = `${level}_${group}`;

  if (!grouped[key]) {
    grouped[key] = {
      urgency: level,
      work_group: group,
      tasks: []
    };
  }
  grouped[key].tasks.push(task.json);
});

// Format for Mattermost
const attachments = [];
const colors = {
  'overdue': '#FF6B6B',
  'due_today': '#FFD93D',
  'due_1_day': '#FFA500',
  'due_3_days': '#4ECDC4',
  'due_soon': '#95E1D3'
};

const titles = {
  'overdue': '⚠️ Overdue Tasks',
  'due_today': '📋 Tasks Due Today',
  'due_1_day': '⏰ Tasks Due Tomorrow',
  'due_3_days': '📅 Tasks Due in 3 Days',
  'due_soon': '📆 Tasks Due Soon'
};

const workGroupChannels = {
  'bien_tap': '#tasks-bien-tap',
  'hanh_chinh': '#tasks-hanh-chinh',
  'chung': '#tasks-general',
  'default': '#tasks-general'
};

// Determine primary channel
let primaryChannel = '#tasks-general';
let hasUrgent = false;

Object.keys(grouped).forEach(key => {
  const group = grouped[key];
  const level = group.urgency;

  if (level === 'overdue' || level === 'due_today') {
    hasUrgent = true;
    primaryChannel = '#tasks-urgent';
  }

  const tasksInGroup = group.tasks;
  const fields = tasksInGroup.slice(0, 10).map(task => ({
    short: true,
    title: task.title || 'Untitled Task',
    value: `@${task.assignee_username || 'unassigned'}\nDue: ${task.due_date || 'N/A'}\nPriority: ${task.priority || 'normal'}`
  }));

  attachments.push({
    color: colors[level] || '#4ECDC4',
    title: `${titles[level] || 'Tasks'} - ${group.work_group}`,
    fields: fields,
    footer: `Total: ${tasksInGroup.length} task(s)`,
    ts: Math.floor(Date.now() / 1000)
  });
});

// Format email data
const emailTasks = tasks.map(t => t.json);
const overdueCount = emailTasks.filter(t => t.urgency_level === 'overdue').length;
const dueTodayCount = emailTasks.filter(t => t.urgency_level === 'due_today').length;

return {
  json: {
    hasTasks: true,
    totalTasks: tasks.length,
    overdueCount: overdueCount,
    dueTodayCount: dueTodayCount,
    // Mattermost data
    mattermost_text: `📋 **Task Reminder**\n\nYou have ${tasks.length} task(s) requiring attention.`,
    mattermost_channel: primaryChannel,
    mattermost_attachments: attachments,
    // Email data
    email_subject: `📋 Task Reminder: ${overdueCount > 0 ? overdueCount + ' Overdue' : ''} ${dueTodayCount > 0 ? dueTodayCount + ' Due Today' : ''} ${tasks.length} Total`,
    email_tasks: emailTasks,
    // Group by assignee for individual emails
    assignees: [...new Set(emailTasks.map(t => t.assignee_id).filter(Boolean))].map(id => {
      const assigneeTasks = emailTasks.filter(t => t.assignee_id === id);
      const assignee = assigneeTasks[0];
      return {
        assignee_id: id,
        assignee_email: assignee.assignee_email,
        assignee_name: assignee.assignee_name,
        tasks: assigneeTasks
      };
    }),
    // Execution tracking
    execution_id: $execution.id || `exec_${Date.now()}`,
    workflow_name: 'Task Due Reminder'
  }
};

// Format email for each assignee
const assignee = $json;

const emailHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #333; border-bottom: 2px solid #4ECDC4; padding-bottom: 10px;">📋 Task Reminder</h2>

  <p>Dear ${assignee.assignee_name},</p>

  <p>You have <strong>${assignee.tasks.length}</strong> task(s) requiring your attention:</p>

  <table style="width: 100%; border-collapse: collapse; margin: 20px 0; background: #f9f9f9;">
    <thead>
      <tr style="background: #4ECDC4; color: white;">
        <th style="padding: 12px; text-align: left;">Task</th>
        <th style="padding: 12px; text-align: left;">Due Date</th>
        <th style="padding: 12px; text-align: left;">Priority</th>
        <th style="padding: 12px; text-align: left;">Status</th>
      </tr>
    </thead>
    <tbody>
      ${assignee.tasks.map(task => {
        const urgencyColor = task.urgency_level === 'overdue' ? '#FF6B6B' : 
                            task.urgency_level === 'due_today' ? '#FFD93D' : '#4ECDC4';
        return `
        <tr>
          <td style="padding: 12px; border-bottom: 1px solid #ddd;">${task.title || 'Untitled'}</td>
          <td style="padding: 12px; border-bottom: 1px solid #ddd; color: ${urgencyColor};"><strong>${task.due_date || 'N/A'}</strong></td>
          <td style="padding: 12px; border-bottom: 1px solid #ddd;">${task.priority || 'normal'}</td>
          <td style="padding: 12px; border-bottom: 1px solid #ddd;">${task.status || 'pending'}</td>
        </tr>`;
      }).join('')}
    </tbody>
  </table>

  <p style="margin-top: 30px;">Please review and complete these tasks as soon as possible.</p>

  <p style="margin-top: 30px;">Best regards,<br><strong>OrientClassicsManager System</strong></p>
</div>
`;

return {
  json: {
    to: assignee.assignee_email,
    subject: `📋 Task Reminder: ${assignee.tasks.length} task(s) require attention`,
    html: emailHtml,
    assignee_name: assignee.assignee_name,
    task_count: assignee.tasks.length
  }
};
